import React, { useState, useEffect } from 'react';

function BookingModal({ event, onConfirm, onClose }) {
  const [userName, setUserName] = useState('');
  const [error, setError]       = useState('');

  /* Close on Escape key */
  useEffect(() => {
    const handler = (e) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [onClose]);

  const handleSubmit = () => {
    if (!userName.trim()) { setError('Please enter your name.'); return; }
    onConfirm(event.id, userName.trim());
  };

  const pct = event.total_seats > 0 ? (event.available_seats / event.total_seats) * 100 : 0;
  const barColor = pct === 0 ? '#ef4444' : pct < 30 ? '#f59e0b' : '#22c55e';

  return (
    /* Backdrop */
    <div
      onClick={onClose}
      style={{
        position: 'fixed', inset: 0, zIndex: 1000,
        background: 'rgba(0,0,0,.65)',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        backdropFilter: 'blur(4px)',
      }}
    >
      {/* Panel — stop click propagation so clicking inside doesn't close */}
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          background: 'var(--surface)',
          border: '1px solid var(--border)',
          borderRadius: 12,
          width: '100%', maxWidth: 420,
          padding: 28,
          boxShadow: '0 24px 64px rgba(0,0,0,.6)',
        }}
      >
        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 20 }}>
          <div>
            <div style={{ fontSize: 16, fontWeight: 600, marginBottom: 2 }}>Confirm Booking</div>
            <div style={{ fontSize: 12, color: 'var(--muted)' }}>Press Esc to close</div>
          </div>
          <button onClick={onClose} style={{
            background: 'none', border: 'none', color: 'var(--muted)',
            fontSize: 20, cursor: 'pointer', lineHeight: 1, padding: 2,
          }}>×</button>
        </div>

        {/* Event info card */}
        <div style={{
          background: 'var(--surface2)', border: '1px solid var(--border)',
          borderRadius: 8, padding: '14px 16px', marginBottom: 20,
        }}>
          <div style={{ fontWeight: 500, marginBottom: 4 }}>{event.name}</div>
          {event.description && (
            <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 10 }}>{event.description}</div>
          )}
          <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 8 }}>
            {new Date(event.date).toLocaleString()}
          </div>

          {/* Seat bar */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <div style={{ flex: 1, height: 4, background: 'var(--border)', borderRadius: 2, overflow: 'hidden' }}>
              <div style={{ width: `${pct}%`, height: '100%', background: barColor, borderRadius: 2 }} />
            </div>
            <span style={{ fontSize: 12, fontFamily: 'var(--mono)', color: barColor, whiteSpace: 'nowrap' }}>
              {event.available_seats} / {event.total_seats} seats
            </span>
          </div>
        </div>

        {/* Name input */}
        <div style={{ marginBottom: 6 }}>
          <label>Your Name *</label>
          <input
            type="text"
            value={userName}
            onChange={(e) => { setUserName(e.target.value); setError(''); }}
            placeholder="Enter your full name"
            onKeyDown={(e) => { if (e.key === 'Enter') handleSubmit(); }}
            autoFocus
          />
        </div>

        {error && (
          <div style={{ fontSize: 12, color: 'var(--danger)', marginBottom: 12, marginTop: 6 }}>{error}</div>
        )}

        {/* Actions */}
        <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end', marginTop: 20 }}>
          <button className="btn btn-ghost" onClick={onClose}>Cancel</button>
          <button className="btn btn-primary" onClick={handleSubmit}>
            Confirm Booking
          </button>
        </div>
      </div>
    </div>
  );
}

export default BookingModal;
